export const productSlugBase = (name: string, sku: string) =>
  (slugText(name) || slugText(sku) || 'produkt').slice(0, 110).replace(/-$/u, '');

const newProductSlug = (products: readonly Product[], name: string, sku: string) => {
  const base = productSlugBase(name, sku);
  const taken = new Set(
    products.flatMap((product) => (product.slug === undefined ? [] : [product.slug.trim().toLowerCase()])),
  );
  let slug = base;
  let suffix = 2;
  while (taken.has(slug)) {
    slug = `${base}-${suffix}`;
    suffix += 1;
  }
  return slug;
};

