const StockBalanceKeySchema = Schema.fromJsonString(
  Schema.Tuple([ProductIdSchema, Schema.OptionFromNullOr(VariantIdSchema)]),
);
const encodeStockBalanceKey = Schema.encodeResult(StockBalanceKeySchema);

/** Return only the outstanding ORDER debit per product/variant; cancel + remove never double-credits. */
const returnOrderStock = (state: MerchandiseState, order: Order, input: MerchandiseCommandInput, note: string) => {
  const balances = new Map<
    string,
    { delta: number; productId: StockMovement['productId']; variantId?: NonNullable<StockMovement['variantId']> }
  >();
  for (const movement of state.movements) {
    if (movement.reason !== 'ORDER' || movement.reference !== order.number) {
      continue;
    }
    const key = Result.getOrThrow(
      encodeStockBalanceKey([movement.productId, Option.fromUndefinedOr(movement.variantId)]),
    );
    const previous = balances.get(key);
    balances.set(key, {
      productId: movement.productId,
      ...stockVariantFields(movement.variantId),
      delta: (previous?.delta ?? 0) + movement.delta,
    });
  }
  return Effect.forEach(
    [...balances.values()].filter((balance) => balance.delta < 0),
    (balance, index) =>
      movementIdOf(input.resourceId, index).pipe(
        Effect.map((id): StockMovement => ({
          ...balance,
          at: input.now,
          delta: -balance.delta,
          id,
          note,
          reason: 'ORDER',
          reference: order.number,
        })),
      ),
    { concurrency: 1 },
  );
};

/** Cancelling returns the order's outstanding stock debit. */
const changeOrderStatus = Effect.fn('Merchandise.changeOrderStatus')(function* changeOrderStatus(
  state: MerchandiseState,
  value: CommandOf<'ChangeOrderStatus'>,
  input: MerchandiseCommandInput,
) {
  const existing = state.orders.find((entry) => entry.id === value.id);
  if (existing === undefined) {
    return yield* notFound(ORDER_NOT_FOUND_REASON);
  }
  if (existing.demoCleanup !== undefined) {
    return yield* conflict('Odstraněnou DEMO objednávku nelze dále zpracovávat');
  }
  const allowed: readonly OrderStatus[] = orderTransitions[existing.status];
  const terminalDemoCancel =
    existing.demo === true &&
    existing.channel === 'STOREFRONT' &&
    (existing.status === 'SHIPPED' || existing.status === 'DELIVERED') &&
    value.status === 'CANCELLED';
  if (!allowed.includes(value.status) && !terminalDemoCancel) {
    return yield* conflict('The requested order transition is not allowed');
  }
  const updated: Order = {
    ...existing,
    history: [
      ...(existing.history ?? []),
      historyEntry(input, {
        after: orderStatusLabels[value.status],
        before: orderStatusLabels[existing.status],
        kind: 'STATUS',
        ...historyReason(value.reason),
      }),
    ],
    status: value.status,
    updatedAt: input.now,
  };
  const orders = state.orders.map((entry) => (entry.id === updated.id ? updated : entry));
  const entity = yield* entityIdOf(existing.id);
  if (value.status !== 'CANCELLED' || !orderMovesStock(state, existing)) {
    return { entityIds: [entity], state: { ...state, orders } };
  }
  const restored = yield* returnOrderStock(state, existing, input, `Storno objednávky ${existing.number}`);
  return { entityIds: [entity], state: { ...state, movements: [...state.movements, ...restored], orders } };
});

const availabilityMessage = {
  IN_STOCK: 'Skladem',
  LOW_STOCK: 'Poslední kusy',
  OUT_OF_STOCK: 'Momentálně není skladem',
  UNKNOWN: 'Dostupnost nyní nelze ověřit',
} satisfies Readonly<Record<Availability, string>>;

const storefrontLines = (order: Pick<Order, 'lines' | 'pricesIncludeVat'>): StorefrontOrderResult['lines'] =>
  order.lines.map((line) => ({
    lineTotalMinor: lineGrossMinor(line, order.pricesIncludeVat),
    name: line.productName,
    productId: line.productId,
    quantity: line.quantity,
    sku: line.sku,
    unitPriceMinor: line.unitPriceMinor,
    ...variantFields(line.variantId, line.variantName),
  }));
const storefrontResultOf = (order: Order, outcome: 'PLACED' | 'REPLAYED'): StorefrontOrderResult => {
  const result: Mutable<StorefrontOrderResult> = {
    issues: [],
    lines: storefrontLines(order),
    orderId: order.id,
    orderNumber: order.number,
    outcome,
    status: order.status,
    totalMinor: order.totalMinor,
    totalVatMinor: order.totalVatMinor,
  };
  if (order.shipping !== undefined) {
    result.shippingPriceMinor = order.shipping.priceMinor;
  }
  return result;
};

interface PricedUnit {
  readonly availability: Availability;
  readonly grossPriceMinor: number;
  readonly minimumQuantity?: number;
  readonly name: string;
  readonly packageQuantity?: number | undefined;
  readonly sku: string;
  readonly stock: number;
  readonly unitLabel: string;
  readonly variantId?: OrderLine['variantId'];
  readonly variantName?: string;
}

export const tierPriceForQuantity = (tiers: Product['priceTiers'], quantity: number): number | undefined =>
  tiers?.filter((tier) => tier.minimumQuantity <= quantity).toSorted((a, b) => b.minimumQuantity - a.minimumQuantity)[0]
    ?.priceMinor;

/** Resolves the sellable unit (product or variant) of one storefront line, or the issue blocking it. */
const sellableUnitOf = (
  products: readonly Product[],
  movements: readonly StockMovement[],
  line: CommandOf<'PlaceStorefrontOrder'>['lines'][number],
): { readonly issue: StorefrontIssue } | { readonly product: Product; readonly unit: PricedUnit } => {
  const product = products.find((entry) => entry.id === line.productId);
  const ids = { productId: line.productId, ...stockVariantFields(line.variantId) };
  if (product === undefined || !product.active || product.published === false) {
    return { issue: { ...ids, code: 'NOT_AVAILABLE', message: 'Produkt už není v nabídce.' } };
  }
  const record = toProductRecord(product, stockLevelsOf(movements, product.id));
  const variants = record.variantRecords ?? [];
  if (variants.length > 0) {
    const variant = variants.find((entry) => entry.id === line.variantId);
    if (variant === undefined) {
      return {
        issue: { ...ids, code: 'VARIANT_REQUIRED', message: `Vyberte prosím variantu produktu ${product.name}.` },
      };
    }
    if (!variant.active) {
      return {
        issue: { ...ids, code: 'NOT_AVAILABLE', message: `Varianta ${variant.name} už není v nabídce.` },
      };
    }
    return {
      product,
      unit: {
        availability: variant.availability,
        grossPriceMinor: tierPriceForQuantity(variant.priceTiers, line.quantity) ?? variant.grossPriceMinor,
        minimumQuantity: variant.minimumQuantity ?? 1,
        name: product.name,
        packageQuantity: variant.packageQuantity,
        sku: variant.sku,
        stock: variant.stockOnHand,
        unitLabel: variant.unit ?? product.unit,
        variantId: variant.id,
        variantName: variant.name,
      },
    };
  }
  return {
    product,
    unit: {
      availability: record.availability ?? 'UNKNOWN',
      grossPriceMinor:
        tierPriceForQuantity(product.priceTiers, line.quantity) ??
        record.grossPriceMinor ??
        grossUnitPriceMinor(product.currentPriceMinor, product.vatRate),
      minimumQuantity: product.minimumQuantity ?? 1,
      name: product.name,
      packageQuantity: product.packageQuantity,
      sku: product.sku,
      stock: record.stockOnHand,
      unitLabel: product.unit,
    },
  };
};

type StorefrontLineRequest = CommandOf<'PlaceStorefrontOrder'>['lines'][number];
const checkedStorefrontUnit = (
  state: MerchandiseState,
  line: StorefrontLineRequest,
  requested: Map<string, number>,
): ReturnType<typeof sellableUnitOf> => {
  const resolved = sellableUnitOf(state.products, state.movements, line);
  if ('issue' in resolved) {
    return resolved;
  }
  const { product, unit } = resolved;
  const ids = { productId: product.id, ...stockVariantFields(unit.variantId) };
  const key = `${product.id}|${unit.variantId ?? ''}`;
  const quantity = (requested.get(key) ?? 0) + line.quantity;
  requested.set(key, quantity);
  const label = unit.variantName === undefined ? unit.name : `${unit.name} (${unit.variantName})`;
  // A zero or missing owner price is never sellable, whatever price the storefront claims it saw.
  if (!Number.isSafeInteger(unit.grossPriceMinor) || unit.grossPriceMinor <= 0) {
    return {
      issue: {
        ...ids,
        code: 'PRICE_UNAVAILABLE',
        message: `${label}: cena není dostupná, položku proto nelze objednat.`,
      },
    };
  }
  if (line.quantity < (unit.minimumQuantity ?? 1)) {
    return {
      issue: {
        ...ids,
        code: 'MINIMUM_QUANTITY',
        message: `${label}: minimální množství je ${unit.minimumQuantity}.`,
      },
    };
  }
  if (
    unit.packageQuantity !== undefined &&
    unit.packageQuantity > 0 &&
    Math.abs(line.quantity / unit.packageQuantity - Math.round(line.quantity / unit.packageQuantity)) > 0.000001
  ) {
    return {
      issue: {
        ...ids,
        code: 'PACKAGE_QUANTITY',
        message: `${label}: objednávejte v násobcích balení ${unit.packageQuantity}.`,
      },
    };
  }
  if (unit.availability === 'UNKNOWN') {
    return {
      issue: {
        ...ids,
        availability: unit.availability,
        code: 'AVAILABILITY_UNKNOWN',
        message: `${label}: dostupnost nyní nelze ověřit, objednávku proto nelze dokončit.`,
      },
    };
  }
  if (unit.availability === 'OUT_OF_STOCK') {
    return {
      issue: {
        ...ids,
        availability: unit.availability,
        availableQuantity: 0,
        code: 'OUT_OF_STOCK',
        message: `${label}: ${availabilityMessage.OUT_OF_STOCK.toLowerCase()}.`,
      },
    };
  }
  if (unit.stock < quantity) {
    return {
      issue: {
        ...ids,
        availability: unit.availability,
        availableQuantity: unit.stock,
        code: 'INSUFFICIENT_STOCK',
        message: `${label}: k dispozici je jen ${unit.stock} ${unit.unitLabel}.`,
      },
    };
  }
  if (unit.grossPriceMinor !== line.expectedUnitPriceMinor) {
    return {
      issue: {
        ...ids,
        code: 'PRICE_CHANGED',
        currentUnitPriceMinor: unit.grossPriceMinor,
        expectedUnitPriceMinor: line.expectedUnitPriceMinor,
        message: `${label}: cena se změnila z ${czk(line.expectedUnitPriceMinor)} na ${czk(unit.grossPriceMinor)}. Potvrďte prosím novou cenu.`,
      },
    };
  }
  return resolved;
};

const placeStorefrontOrder = Effect.fn('Merchandise.placeStorefrontOrder')(function* placeStorefrontOrder(
  state: MerchandiseState,
  value: CommandOf<'PlaceStorefrontOrder'>,
  input: MerchandiseCommandInput,
) {
  const replay = state.orders.find((entry) => entry.clientRequestId === value.clientRequestId);
  if (replay !== undefined) {
    if (replay.customerAccountId !== value.customerAccountId) {
      return yield* conflict('Submission belongs to another customer');
    }
    const entity = yield* entityIdOf(replay.id);
    return { entityIds: [entity], state, storefrontOrder: storefrontResultOf(replay, 'REPLAYED') };
  }
  const issues: StorefrontIssue[] = [];
  const lines: OrderLine[] = [];
  const requested = new Map<string, number>();
  yield* Effect.forEach(
    value.lines,
    Effect.fn('Merchandise.storefrontLine')(function* storefrontLine(line: StorefrontLineRequest) {
      const resolved = checkedStorefrontUnit(state, line, requested);
      if ('issue' in resolved) {
        issues.push(resolved.issue);
        return;
      }
      const { product, unit } = resolved;
      const snapshot: Mutable<OrderLine> = {
        productId: product.id,
        productName: product.name,
        quantity: line.quantity,
        sku: unit.sku,
        unitPriceMinor: unit.grossPriceMinor,
        vatRate: product.vatRate,
      };
      if (unit.variantId !== undefined) {
        snapshot.variantId = yield* mintId(VariantIdSchema, unit.variantId);
      }
      if (unit.variantName !== undefined) {
        snapshot.variantName = unit.variantName;
      }
      lines.push(snapshot);
    }),
    { concurrency: 1, discard: true },
  );
  const method = shippingMethodFor(value.shippingMethod, isSourceCatalog(state));
  if (value.expectedShippingPriceMinor !== undefined && value.expectedShippingPriceMinor !== method.grossPriceMinor) {
    issues.push({
      code: 'SHIPPING_PRICE_CHANGED',
      currentUnitPriceMinor: method.grossPriceMinor,
      expectedUnitPriceMinor: value.expectedShippingPriceMinor,
      message: `Cena dopravy se změnila na ${czk(method.grossPriceMinor)}.`,
    });
  }
  const shipping = {
    label: method.label,
    method: value.shippingMethod,
    priceMinor: method.grossPriceMinor,
    vatRate: 21,
  } as const;
  const draftTotals = fullOrderTotals({ lines, pricesIncludeVat: true, shipping });
  const draftLines = storefrontLines({ lines, pricesIncludeVat: true });
  if (issues.length > 0 || value.dryRun === true) {
    const storefrontOrder: StorefrontOrderResult = {
      issues,
      lines: draftLines,
      outcome: issues.length > 0 ? 'REJECTED' : 'VALID',
      shippingPriceMinor: method.grossPriceMinor,
      ...draftTotals,
    };
    return { entityIds: [], state, storefrontOrder };
  }
  if (value.contact === undefined || value.deliveryAddress === undefined || value.partyId === undefined) {
    return yield* conflict('Order contact, delivery address and customer party are required');
  }
  const id = yield* mintId(OrderIdSchema, input.resourceId);
  if (state.orders.some((entry) => entry.id === id)) {
    return yield* conflict('Order id already exists');
  }
  const number = nextOrderNumberOf(state);
  const order: Mutable<Order> = {
    channel: 'STOREFRONT',
    clientRequestId: ClientRequestIdSchema.make(value.clientRequestId),
    contact: value.contact,
    createdAt: input.now,
    deliveryAddress: value.deliveryAddress,
    history: [
      {
        actorLabel: 'Zákazník – e-shop',
        after: orderStatusLabels.NEW,
        at: input.now,
        kind: 'CREATED',
      },
    ],
    id,
    lines,
    number,
    partyId: value.partyId,
    pricesIncludeVat: true,
    shipping,
    status: 'NEW',
    ...draftTotals,
    updatedAt: input.now,
  };
  if (value.billingAddress !== undefined) {
    order.billingAddress = value.billingAddress;
  }
  if (value.customerAccountId !== undefined) {
    order.customerAccountId = value.customerAccountId;
  }
  if (value.deliveryRecipient !== undefined) {
    order.deliveryRecipient = value.deliveryRecipient;
  }
  if (value.note !== undefined && value.note !== '') {
    order.note = value.note;
  }
  const entity = yield* entityIdOf(order.id);
  // Atomic with the order: the same save writes one ORDER movement per line; cancelling returns it.
  const placedMovements = yield* Effect.forEach(
    lines,
    (line, index) =>
      movementIdOf(input.resourceId, index).pipe(
        Effect.map((movementId): StockMovement => ({
          at: input.now,
          delta: -line.quantity,
          id: movementId,
          note: `Objednávka ${number} z e-shopu`,
          productId: line.productId,
          reason: 'ORDER',
          reference: number,
          ...stockVariantFields(line.variantId),
        })),
      ),
    { concurrency: 1 },
  );
  return {
    entityIds: [entity],
    state: { ...state, movements: [...state.movements, ...placedMovements], orders: [...state.orders, order] },
    storefrontOrder: storefrontResultOf(order, 'PLACED'),
  };
});

const describeLine = (line: OrderLine, pricesIncludeVat = false) => {
  const variant = line.variantName === undefined ? '' : ` (${line.variantName})`;
  const net = pricesIncludeVat ? '' : ' bez DPH';
  return `${line.quantity}× ${line.productName}${variant} á ${czk(line.unitPriceMinor)}${net}`;
};
export const describeLines = (order: {
  readonly lines: readonly OrderLine[];
  readonly pricesIncludeVat?: boolean | undefined;
}) => order.lines.map((line) => describeLine(line, order.pricesIncludeVat)).join('; ');
export const describeAddress = (address: Order['deliveryAddress']) => {
  if (address === undefined) {
    return 'bez adresy';
  }
  const country = address.country === undefined || address.country === '' ? '' : `, ${address.country}`;
  return `${address.street}, ${address.postalCode} ${address.city}${country}`;
};

export const describeContact = (contact: Order['contact']) =>
  contact === undefined
    ? 'bez kontaktu'
    : [contact.name, contact.email, contact.phone].filter((part) => part !== undefined && part !== '').join(', ');

export const describeShipping = (shipping: Order['shipping']) =>
  shipping === undefined ? 'bez dopravy' : `${shipping.label}, ${czk(shipping.priceMinor)}`;

const lineKey = (line: { readonly productId: string; readonly variantId?: string | undefined }) =>
  `${line.productId}|${line.variantId ?? ''}`;

/** Edits an open order; stock-moving (staff) orders reconcile their ORDER movements for quantity changes. */
type EditLineRequest = NonNullable<CommandOf<'EditOrder'>['lines']>[number];
const validateEditedStorefrontQuantity = Effect.fn('Merchandise.validateEditedStorefrontQuantity')(
  function* validateEditedStorefrontQuantity(
    state: MerchandiseState,
    existing: Order,
    request: EditLineRequest,
    kept: OrderLine | undefined,
  ) {
    if (existing.channel === 'STOREFRONT' && kept?.quantity !== request.quantity) {
      const product = yield* findProduct(state.products, request.productId);
      const record = toProductRecord(product, stockLevelsOf(state.movements, product.id));
      const unit =
        request.variantId === undefined
          ? record
          : record.variantRecords?.find((variant) => variant.id === request.variantId);
      const alreadyDebitedQuantity = orderMovesStock(state, existing) ? (kept?.quantity ?? 0) : 0;
      if (
        unit === undefined ||
        !isOrderQuantityValid(request.quantity, orderQuantityRules(unit, alreadyDebitedQuantity))
      ) {
        return yield* conflict('Množství musí odpovídat dostupné zásobě, minimu a velikosti balení varianty');
      }
    }
    return yield* Effect.void;
  },
);

const editedOrderLines = Effect.fn('Merchandise.editedOrderLines')(function* editedOrderLines(
  state: MerchandiseState,
  existing: Order,
  incoming: readonly EditLineRequest[],
) {
  const previous = new Map(existing.lines.map((line) => [lineKey(line), line] as const));
  const seen = new Set<string>();
  return yield* Effect.forEach(
    incoming,
    Effect.fn('Merchandise.editedOrderLine')(function* editedOrderLine(request: EditLineRequest) {
      const key = lineKey(request);
      if (seen.has(key)) {
        return yield* conflict('Each product variant may appear only once in an order');
      }
      seen.add(key);
      const kept = previous.get(key);
      yield* validateEditedStorefrontQuantity(state, existing, request, kept);
      if (kept !== undefined) {
        return {
          ...kept,
          quantity: request.quantity,
          unitPriceMinor: request.unitPriceMinor ?? kept.unitPriceMinor,
        };
      }
      const product = yield* findProduct(state.products, request.productId);
      const variant = request.variantId === undefined ? undefined : yield* findVariant(product, request.variantId);
      if (variant === undefined && realVariantsOf(product).length > 0) {
        return yield* conflict(`Choose a variant of ${product.sku}`);
      }
      const netPrice = variant?.priceMinor ?? product.currentPriceMinor;
      const currentPrice =
        existing.pricesIncludeVat === true ? grossUnitPriceMinor(netPrice, product.vatRate) : netPrice;
      return {
        productId: product.id,
        productName: product.name,
        quantity: request.quantity,
        sku: variant?.sku ?? product.sku,
        unitPriceMinor: request.unitPriceMinor ?? currentPrice,
        ...variantFields(variant?.id, variant?.name),
        vatRate: product.vatRate,
      };
    }),
    { concurrency: 1 },
  );
});

const reconciledOrderMovements = Effect.fn('Merchandise.reconcileOrderMovements')(function* reconciledOrderMovements(
  state: MerchandiseState,
  existing: Order,
  nextLines: readonly OrderLine[],
  input: MerchandiseCommandInput,
) {
  const quantities = new Map<string, { delta: number; line: OrderLine }>();
  for (const line of existing.lines) {
    const key = lineKey(line);
    const entry = quantities.get(key);
    quantities.set(key, { delta: (entry?.delta ?? 0) + line.quantity, line });
  }
  for (const line of nextLines) {
    const entry = quantities.get(lineKey(line));
    quantities.set(lineKey(line), { delta: (entry?.delta ?? 0) - line.quantity, line });
  }
  const changed = [...quantities.values()].filter(({ delta }) => delta !== 0);
  const added = yield* Effect.forEach(
    changed,
    Effect.fn('Merchandise.reconcileOrderLine')(function* reconcileOrderLine(
      { delta, line }: { readonly delta: number; readonly line: OrderLine },
      index: number,
    ) {
      const stock =
        line.variantId === undefined
          ? stockOnHandOf(state.movements, line.productId)
          : variantStockOf(state.movements, line.productId, line.variantId);
      if (stock + delta < 0) {
        return yield* conflict(`Insufficient stock for ${line.sku}`);
      }
      return {
        at: input.now,
        delta,
        id: yield* movementIdOf(input.resourceId, index),
        productId: line.productId,
        reason: 'ORDER' as const,
        reference: existing.number,
        ...stockVariantFields(line.variantId),
      };
    }),
    { concurrency: 1 },
  );
  return [...state.movements, ...added];
});

const editedOrderDetails = (
  state: MerchandiseState,
  existing: Order,
  initial: Order,
  value: CommandOf<'EditOrder'>,
  input: MerchandiseCommandInput,
) => {
  let order = initial;
  const history: OrderHistoryEntry[] = [];
  const reason = value.reason === undefined || value.reason === '' ? {} : { reason: value.reason };
  if (value.shipping !== undefined) {
    const method = shippingMethodFor(value.shipping.method, isSourceCatalog(state));
    const shipping = {
      label: method.label,
      method: value.shipping.method,
      priceMinor: value.shipping.priceMinor,
      vatRate: 21,
    } as const;
    const before = describeShipping(existing.shipping);
    const after = describeShipping(shipping);
    if (before !== after) {
      order = { ...order, shipping };
      history.push(historyEntry(input, { after, before, kind: 'SHIPPING', ...reason }));
    }
  }
  if (value.deliveryAddress !== undefined) {
    const before = describeAddress(existing.deliveryAddress);
    const after = describeAddress(value.deliveryAddress);
    if (before !== after) {
      order = { ...order, deliveryAddress: value.deliveryAddress };
      history.push(historyEntry(input, { after, before, kind: 'ADDRESS', ...reason }));
    }
  }
  if (value.contact !== undefined) {
    const before = describeContact(existing.contact);
    const after = describeContact(value.contact);
    if (before !== after) {
      order = { ...order, contact: value.contact };
      history.push(historyEntry(input, { after, before, kind: 'CONTACT', ...reason }));
    }
  }
  if (value.note !== undefined && value.note !== (existing.note ?? '')) {
    order = { ...order, note: value.note };
    history.push(
      historyEntry(input, {
        after: value.note === '' ? 'bez poznámky' : value.note,
        before: existing.note ?? 'bez poznámky',
        kind: 'NOTE',
        ...reason,
      }),
    );
  }
  return { history, order };
};

const editOrder = Effect.fn('Merchandise.editOrder')(function* editOrder(
  state: MerchandiseState,
  value: CommandOf<'EditOrder'>,
  input: MerchandiseCommandInput,
) {
  const existing = state.orders.find((entry) => entry.id === value.id);
  if (existing === undefined) {
    return yield* notFound(ORDER_NOT_FOUND_REASON);
  }
  if (
    existing.demoCleanup !== undefined ||
    existing.status === 'DELIVERED' ||
    existing.status === 'CANCELLED' ||
    existing.status === 'SHIPPED'
  ) {
    return yield* conflict('Only open orders before the carrier hand-over can be edited');
  }
  const history: OrderHistoryEntry[] = [];
  const reason = value.reason === undefined || value.reason === '' ? {} : { reason: value.reason };
  let order = existing;
  let { movements } = state;
  if (value.lines !== undefined) {
    const nextLines = yield* editedOrderLines(state, existing, value.lines);
    const before = describeLines(existing);
    const after = describeLines({ lines: nextLines, pricesIncludeVat: existing.pricesIncludeVat });
    if (before !== after) {
      if (orderMovesStock(state, existing)) {
        movements = yield* reconciledOrderMovements(state, existing, nextLines, input);
      }
      order = { ...order, lines: nextLines };
      history.push(historyEntry(input, { after, before, kind: 'LINES', ...reason }));
    }
  }
  const details = editedOrderDetails(state, existing, order, value, input);
  history.push(...details.history);
  const entity = yield* entityIdOf(existing.id);
  if (history.length === 0) {
    return { entityIds: [entity], state };
  }
  const updated: Order = {
    ...details.order,
    ...fullOrderTotals(details.order),
    history: [...(existing.history ?? []), ...history],
    updatedAt: input.now,
  };
  return {
    entityIds: [entity],
    state: { ...state, movements, orders: state.orders.map((entry) => (entry.id === updated.id ? updated : entry)) },
  };
});

/** An order edit that names the order version it was made against; see `EditOrder.expectedUpdatedAt`. */
const OrderScopedEditSchema = Schema.TaggedStruct('EditOrder', {
  expectedUpdatedAt: Schema.DateTimeUtcFromString,
});
export const isOrderScopedEdit = (
  command: MerchandiseCommand,
): command is Extract<MerchandiseCommand, { readonly _tag: 'EditOrder' }> & {
  readonly expectedUpdatedAt: DateTime.Utc;
} => Schema.is(OrderScopedEditSchema)(command);

/** Applies one command to the state. Pure: persistence decides when the result is saved. */
export const evolveMerchandiseState = (
  state: MerchandiseState,
  command: MerchandiseCommand,
  input: MerchandiseCommandInput,
): Effect.Effect<MerchandiseChange, MerchandiseCommandError> =>
  Match.value(command).pipe(
    Match.tag('CreateProduct', (value) => addProduct(state, value, input)),
    Match.tag('UpdateProduct', (value) => updateProduct(state, value, input)),
    Match.tag('ChangePrice', (value) => changePrice(state, value, input)),
    Match.tag('BulkUpdateProducts', (value) => bulkUpdateProducts(state, value, input)),
    Match.tag('RecordStockMovement', (value) => recordStockMovement(state, value, input)),
    Match.tag('CreateOrder', (value) => placeOrder(state, value, input)),
    Match.tag('ChangeOrderStatus', (value) => changeOrderStatus(state, value, input)),
    Match.tag('PlaceStorefrontOrder', (value) => placeStorefrontOrder(state, value, input)),
    Match.tag('EditOrder', (value) => editOrder(state, value, input)),
    Match.tag(
      'LinkOrderCustomer',
      Effect.fn('Merchandise.linkOrderCustomer')(function* linkCustomer(
        value: Extract<MerchandiseCommand, { readonly _tag: 'LinkOrderCustomer' }>,
      ) {
        const order = state.orders.find((entry) => entry.id === value.id && entry.demoCleanup === undefined);
        if (order === undefined) {
          return yield* notFound('Objednávka neexistuje');
        }
        const entity = yield* entityIdOf(order.id);
        if (order.partyId === value.partyRef.resourceId) {
          return { entityIds: [entity], state };
        }
        if (order.channel !== 'STOREFRONT' || order.partyId !== value.expectedPartyId) {
          return yield* conflict('Zákazník objednávky se změnil; obnovte detail');
        }
        const partyId = yield* Schema.decodeEffect(PartyIdSchema)(value.partyRef.resourceId).pipe(
          Effect.catchTag('SchemaError', () => Effect.fail(conflict('Neplatný zákazník'))),
        );
        const updated: Order = {
          ...order,
          history: [
            ...(order.history ?? []),
            historyEntry(input, {
              after: partyId,
              before: order.partyId,
              kind: 'CONTACT',
              reason: 'Převod na zákazníka',
            }),
          ],
          partyId,
          updatedAt: input.now,
        };
        return {
          entityIds: [entity],
          state: {
            ...state,
            orders: state.orders.map((entry) => (entry.id === order.id ? updated : entry)),
          },
        };
      }),
    ),
    Match.tag('UpdateCategory', (value) => updateCategoryCommand(state, value, input)),
    // Replaces every row of the company in parts, so persistence (applyOnce) performs it; the pure evolve never does.
    Match.tag('ResetDemoData', () => Effect.fail(conflict('Demo reset runs only through persistence'))),
    Match.tag(
      'ArchiveDemoProduct',
      Effect.fn('Merchandise.archiveDemoProduct')(function* archiveDemoProduct(value: CommandOf<'ArchiveDemoProduct'>) {
        const product = yield* findProduct(state.products, value.id);
        const entity = yield* entityIdOf(product.id);
        if (product.active || product.published !== false) {
          return yield* conflict('Před archivací produkt deaktivujte a skryjte v e-shopu');
        }
        if (product.demoArchive !== undefined) {
          return { entityIds: [entity], state };
        }
        const archived = withContentHistory(
          product,
          {
            ...product,
            active: false,
            demoArchive: { actor: input.actor, at: input.now, reason: value.reason },
            published: false,
            updatedAt: input.now,
          },
          input,
        );
        return { entityIds: [entity], state: withProduct(state, archived) };
      }),
    ),
    Match.tag(
      'RemoveDemoOrder',
      Effect.fn('Merchandise.removeDemoOrder')(function* removeDemoOrder(value: CommandOf<'RemoveDemoOrder'>) {
        const order = state.orders.find((entry) => entry.id === value.id);
        if (order === undefined) {
          return yield* notFound(ORDER_NOT_FOUND_REASON);
        }
        if (order.demo !== true || order.channel !== 'STOREFRONT') {
          return yield* conflict('Odstranit lze pouze DEMO objednávku z e-shopu');
        }
        const entity = yield* entityIdOf(order.id);
        if (order.demoCleanup !== undefined) {
          if (value.repairStock !== true) {
            return { entityIds: [entity], state };
          }
          const returned = yield* returnOrderStock(
            state,
            order,
            input,
            `Dorovnání skladu odstraněné DEMO objednávky ${order.number}`,
          );
          if (returned.length === 0) {
            return { entityIds: [entity], state };
          }
          const repaired: Order = {
            ...order,
            history: [
              ...(order.history ?? []),
              historyEntry(input, {
                after: 'Dorovnán sklad odstraněné DEMO objednávky',
                kind: 'NOTE',
                reason: value.reason,
              }),
            ],
            updatedAt: input.now,
          };
          return {
            entityIds: [entity],
            state: {
              ...state,
              movements: [...state.movements, ...returned],
              orders: state.orders.map((entry) => (entry.id === order.id ? repaired : entry)),
            },
          };
        }
        const removed: Order = {
          ...order,
          demoCleanup: { actor: input.actor, at: input.now, reason: value.reason },
          history: [
            ...(order.history ?? []),
            historyEntry(input, {
              after: 'Odstraněna z prezentačního seznamu; audit zachován',
              before: 'Viditelná DEMO objednávka',
              kind: 'NOTE',
              reason: value.reason,
            }),
          ],
          updatedAt: input.now,
        };
        // All DEMO statuses, including shipped/delivered; the ledger prevents duplicate returns.
        const returned = yield* returnOrderStock(
          state,
          order,
          input,
          `Vráceno – odstraněná DEMO objednávka ${order.number}`,
        );
        return {
          entityIds: [entity],
          state: {
            ...state,
            // Keep the ledger reference when nothing is returned, so no-op removals stay identical.
            movements: returned.length === 0 ? state.movements : [...state.movements, ...returned],
            orders: state.orders.map((entry) => (entry.id === order.id ? removed : entry)),
          },
        };
      }),
    ),
    // AI approval commands need the caller's identity and permission checks, so persistence runs them.
    Match.tag('AiProposeChanges', 'AiDecideChanges', 'AiRevertBatch', () =>
      Effect.fail(conflict('AI approval commands run only through persistence')),
    ),
    Match.exhaustive,
  );

type AiCommand = Extract<
  MerchandiseCommand,
  { readonly _tag: 'AiDecideChanges' | 'AiProposeChanges' | 'AiRevertBatch' }
>;
type AiOperation = Extract<MerchandiseCommand, { readonly _tag: 'ChangeOrderStatus' | 'EditOrder' }>;

const operationNeeds = (operations: readonly AiOperation[]) => ({
  orderIds: operations.map((operation) => operation.id),
  productIds: operations.flatMap((operation) =>
    Match.value(operation).pipe(
      Match.tagsExhaustive({
        ChangeOrderStatus: () => [],
        EditOrder: (value) => (value.lines ?? []).map((line) => line.productId),
      }),
    ),
  ),
});

const SnapshotProductSchema = Schema.Struct({ productId: ProductIdReferenceSchema });
const snapshotProduct = Schema.decodeUnknownResult(SnapshotProductSchema);

/** Rows an AI approval command touches: the proposed orders, their products and the movements a change wrote. */
const aiWorkingSetRequest = (command: AiCommand, slice: MerchandiseState['aiChanges']): WorkingSetRequest => {
  const changes = slice?.changes ?? [];
  const chosen = Match.value(command).pipe(
    Match.tagsExhaustive({
      AiDecideChanges: (value) => changes.filter((change) => value.changeIds.includes(change.id)),
      AiProposeChanges: () => [],
      AiRevertBatch: (value) => changes.filter((change) => change.batchId === value.batchId),
    }),
  );
  const operations: AiOperation[] = Match.value(command).pipe(
    Match.tag('AiProposeChanges', (value) => value.changes.map((change) => change.operation)),
    Match.tag('AiDecideChanges', 'AiRevertBatch', () => chosen.map((change) => change.operation)),
    Match.exhaustive,
  );
  const snapshotProducts = chosen.flatMap((change) =>
    [...(change.snapshots ?? []), ...(change.proposedSnapshots ?? [])].flatMap((snapshot) => {
      if (snapshot.kind !== 'movement') {
        return [];
      }
      return Result.match(snapshotProduct(snapshot.after ?? snapshot.before), {
        onFailure: () => [],
        onSuccess: ({ productId }) => [productId],
      });
    }),
  );
  const needs = operationNeeds(operations);
  return {
    aiChanges: true,
    movements: true,
    orderIds: [
      ...needs.orderIds,
      ...chosen.flatMap((change) => (change.target.id === undefined ? [] : [change.target.id])),
    ],
    productIds: [...needs.productIds, ...snapshotProducts],
    sourceCatalog: true,
  };
};

/** The rows one command reads and may change; nothing else of the company is loaded. */
export const workingSetRequestOf = (
  command: Exclude<MerchandiseCommand, AiCommand | { readonly _tag: 'ResetDemoData' }>,
  resourceId: string,
): WorkingSetRequest =>
  Match.value(command).pipe(
    Match.tagsExhaustive({
      ArchiveDemoProduct: (value): WorkingSetRequest => ({ productIds: [value.id] }),
      BulkUpdateProducts: (value): WorkingSetRequest => ({ productIds: value.ids }),
      ChangeOrderStatus: (value): WorkingSetRequest => ({ movements: true, orderIds: [value.id] }),
      ChangePrice: (value): WorkingSetRequest => ({ productIds: [value.id] }),
      CreateOrder: (value): WorkingSetRequest => ({
        lastOrderNumber: true,
        movements: true,
        orderIds: [value.id],
        productIds: value.lines.map((line) => line.productId),
      }),
      CreateProduct: (value): WorkingSetRequest => ({
        productIds: [resourceId],
        productKeys: {
          sku: value.sku,
          ...(value.slug === undefined ? { slugPrefix: productSlugBase(value.name, value.sku) } : { slug: value.slug }),
        },
      }),
      EditOrder: (value): WorkingSetRequest => ({
        movements: true,
        orderIds: [value.id],
        productIds: (value.lines ?? []).map((line) => line.productId),
        sourceCatalog: true,
      }),
      LinkOrderCustomer: (value): WorkingSetRequest => ({ orderIds: [value.id] }),
      PlaceStorefrontOrder: (value): WorkingSetRequest => ({
        lastOrderNumber: true,
        movements: true,
        orderClientRequestId: value.clientRequestId,
        orderIds: [resourceId],
        productIds: value.lines.map((line) => line.productId),
        sourceCatalog: true,
      }),
      RecordStockMovement: (value): WorkingSetRequest => ({ movements: true, productIds: [value.productId] }),
      RemoveDemoOrder: (value): WorkingSetRequest => ({ movements: true, orderIds: [value.id] }),
      UpdateCategory: (value): WorkingSetRequest => ({ categoryIds: [value.id] }),
      UpdateProduct: (value): WorkingSetRequest => {
        const request: Mutable<WorkingSetRequest> = { productIds: [value.id] };
        if (value.patch.slug !== undefined) {
          request.productKeys = { slug: value.patch.slug };
        }
        if (value.patch.categoryId !== undefined) {
          request.categoryIds = [value.patch.categoryId];
        }
        return request;
      },
    }),
  );

const revisionConflict = (reason = 'Merchandise changed; refresh before another operation') =>
  new MerchandiseRevisionConflict({ code: 'merchandise_revision_conflict', reason });

/** Staff rights a records read needs; the public storefront catalog needs none. */
export interface MerchandiseRecordsGrants {
  readonly administrator: boolean;
  readonly readAll: boolean;
  readonly writeAll: boolean;
}

const recordCapabilities = (
  legalEntityId: string,
  storefront: boolean,
  grants: MerchandiseRecordsGrants,
  canWrite: boolean,
): Pick<RecordsResponse, 'canCleanupDemo' | 'canEditOrders' | 'canManageCatalog' | 'canResetDemo'> => {
  const staff = !storefront;
  const isAdministrator = storefront ? false : grants.administrator;
  const canManageCatalog = canWrite && (legalEntityId !== AKROS_LEGAL_ENTITY_ID || isAdministrator);
  return {
    canCleanupDemo: staff && canWrite && isAdministrator,
    canEditOrders: staff && canManageCatalog,
    canManageCatalog: staff && canManageCatalog,
    canResetDemo: staff && canWrite && isAdministrator && legalEntityId === AKROS_LEGAL_ENTITY_ID,
  };
};

const storefrontCatalogView = (request: RecordsRequest) =>
  request.view?.storefront === true &&
  (request.view.storefrontCatalog !== undefined ||
    request.view.storefrontOrderStatus !== undefined ||
    request.view.storefrontCustomerOrders !== undefined ||
    request.view.storefrontCheckout === true);

/**
 * Resolves a records read's rights before its transaction opens: one bulk check of both catalog permissions
 * and the tenant identity-administrator check, in parallel. The storefront catalog view skips both.
 */
export const merchandiseRecordsGrants = Effect.fn('Merchandise.recordsGrants')(function* merchandiseRecordsGrants(
  scope: OperationalScope,
  request: RecordsRequest,
) {
  if (storefrontCatalogView(request)) {
    return { administrator: false, readAll: false, writeAll: false } satisfies MerchandiseRecordsGrants;
  }
  const access = yield* ContextAccess;
  if (scope.legalEntityId === undefined || access.contextPermissions === undefined) {
    return yield* referenceUnavailable();
  }
  const permissions = ['read_all', 'write_all'] as const;
  const [decisions, tenantDecisions] = yield* Effect.all(
    [
      access.contextPermissions({
        legalEntityId: scope.legalEntityId,
        principalId: scope.principalId,
        targets: permissions.map((permission) => ({
          moduleId: MERCHANDISE_MODULE_ID,
          permission: `demo.merchandise.${permission}`,
        })),
        tenantId: scope.tenantId,
      }),
      request.view?.storefront === true
        ? Effect.succeed([])
        : access.tenants({
            permission: IDENTITY_MANAGEMENT_PERMISSION,
            principalId: scope.principalId,
            tenantIds: [scope.tenantId],
          }),
    ],
    { concurrency: 2 },
  );
  if (
    decisions.length !== permissions.length ||
    decisions.some(
      (decision, index) =>
        decision.key !== `demo.merchandise:demo.merchandise.${permissions[index]}` ||
        decision.decision === 'unavailable',
    )
  ) {
    return yield* referenceUnavailable();
  }
  return {
    // Existing trusted identity-administrator capability; no email, browser flag or principal-id allowlist.
    administrator:
      tenantDecisions.length === 1 &&
      tenantDecisions[0]?.key === scope.tenantId &&
      tenantDecisions[0]?.decision === 'allowed',
    readAll: decisions[0]?.decision === 'allowed',
    writeAll: decisions[1]?.decision === 'allowed',
  } satisfies MerchandiseRecordsGrants;
});

export const persistenceService = Effect.fn('Merchandise.persistenceService')(
  function* makePersistence(transaction: ScopedTransactionExecutor, scope: OperationalScope) {
    const { legalEntityId } = scope;
    if (
      legalEntityId === undefined ||
      transaction.scope.tenantId !== scope.tenantId ||
      transaction.scope.legalEntityId !== legalEntityId
    ) {
      return yield* new MerchandiseScopeMismatch({
        code: 'merchandise_scope_mismatch',
        reason: 'A scoped company transaction is required',
      });
    }
    const store: StoreScope = { legalEntityId, tenantId: scope.tenantId };
    const access = yield* ContextAccess;
    const contextGrant = Effect.fn('Merchandise.contextGrant')(function* contextGrant(
      permission: 'read_all' | 'write_all',
    ) {
      if (access.contextPermissions === undefined) {
        return yield* referenceUnavailable();
      }
      const decisions = yield* access.contextPermissions({
        legalEntityId,
        principalId: scope.principalId,
        targets: [{ moduleId: MERCHANDISE_MODULE_ID, permission: `demo.merchandise.${permission}` }],
        tenantId: scope.tenantId,
      });
      if (
        decisions.length !== 1 ||
        decisions[0]?.key !== `demo.merchandise:demo.merchandise.${permission}` ||
        decisions[0]?.decision === 'unavailable'
      ) {
        return yield* referenceUnavailable();
      }
      return decisions[0]?.decision === 'allowed';
    });
    // Existing trusted identity-administrator capability; no email, browser flag or principal-id allowlist.
    const administrator = Effect.fn('Merchandise.administrator')(function* administrator() {
      const decisions = yield* access.tenants({
        permission: IDENTITY_MANAGEMENT_PERMISSION,
        principalId: scope.principalId,
        tenantIds: [scope.tenantId],
      });
      return decisions.length === 1 && decisions[0]?.key === scope.tenantId && decisions[0]?.decision === 'allowed';
    });
    const lockedHead = Effect.fn('Merchandise.lockedHead')(function* lockedHead(aiChanges: boolean) {
      const head = yield* loadHead(transaction, store, { aiChanges, lock: true }).pipe(Effect.mapError(unavailable));
      return head ?? (yield* unavailable());
    });
    const persist = Effect.fn('Merchandise.persist')(function* persist(
      working: WorkingSet,
      next: MerchandiseState,
      now: DateTime.Utc,
    ) {
      if (next === working.state) {
        return working.revision;
      }
      const revision = yield* persistChange(transaction, store, working, next, now).pipe(Effect.mapError(unavailable));
      return revision ?? (yield* revisionConflict());
    });
    const applyOnce = Effect.fn('Merchandise.applyOnce')(function* applyOnce(
      command: Exclude<MerchandiseCommand, AiCommand>,
      expectedRevision: number,
      resourceId: string,
    ) {
      yield* Match.value(command).pipe(
        Match.tag(
          'LinkOrderCustomer',
          Effect.fn('Merchandise.validateOrderCustomer')(function* validate(
            customerLink: Extract<MerchandiseCommand, { readonly _tag: 'LinkOrderCustomer' }>,
          ) {
            const references = yield* makeReferenceGatewayCredentialSource(scope).pipe(
              Effect.mapError(referenceUnavailable),
            );
            const credential = yield* references.issue('party-registry').pipe(Effect.mapError(referenceUnavailable));
            const customer = yield* executeCounterpartyReadWithAuthorization(
              { counterpartyRef: customerLink.counterpartyRef },
              credential.authorization,
              scope.correlationId,
              { baseUrl: credential.apiBaseUrl, compositionRevision: credential.compositionRevision },
            ).pipe(Effect.mapError(referenceUnavailable));
            const now = DateTime.formatIso(yield* DateTime.now);
            return yield* orderCustomerReferenceEligible(customerLink, customer, store, now)
              ? Effect.void
              : Effect.fail(conflict('Zákazník není aktivním zákazníkem této firmy'));
          }),
        ),
        Match.orElse(() => Effect.void),
      );
      // The head row lock serializes every write of this company; reads never wait for it.
      const head = yield* lockedHead(false);
      // Storefront guests cannot know the revision; their command re-validates against the current rows.
      // An order edit carrying the order's own updatedAt conflicts only when that order changed.
      if (
        !isOrderScopedEdit(command) &&
        !Predicate.isTagged(command, 'PlaceStorefrontOrder') &&
        head.revision !== expectedRevision
      ) {
        return yield* revisionConflict();
      }
      if (Predicate.isTagged(command, 'ResetDemoData')) {
        // Scoped by tenant + legal entity: no other company's rows are read or written.
        const revision = yield* resetToAkrosBaseline(transaction, store).pipe(Effect.mapError(unavailable));
        return { entityIds: [], revision };
      }
      const working = yield* loadWorkingSet(transaction, store, head, workingSetRequestOf(command, resourceId)).pipe(
        Effect.mapError(unavailable),
      );
      if (isOrderScopedEdit(command)) {
        const current = working.state.orders.find((order) => order.id === command.id);
        if (
          current !== undefined &&
          DateTime.toEpochMillis(current.updatedAt) !== DateTime.toEpochMillis(command.expectedUpdatedAt)
        ) {
          return yield* revisionConflict('The order changed; refresh before another edit');
        }
      }
      const now = yield* DateTime.now;
      const actor = { principalId: scope.principalId, tenantId: scope.tenantId };
      const change = yield* evolveMerchandiseState(working.state, command, { actor, now, resourceId });
      const revision = yield* persist(working, change.state, now);
      return change.storefrontOrder === undefined
        ? { entityIds: [...change.entityIds], revision }
        : { entityIds: [...change.entityIds], revision, storefrontOrder: change.storefrontOrder };
    });
    /**
     * AI level C. Proposing needs only read access (the agent principal has no write grant, so it can never change an
     * order directly); deciding and reverting need write_all and a person (command guard), in AKROS an administrator.
     */
    const applyAi = Effect.fn('Merchandise.applyAi')(function* applyAi(
      command: AiCommand,
      expectedRevision: number,
      resourceId: string,
    ) {
      const proposing = Predicate.isTagged(command, 'AiProposeChanges');
      if (!(yield* contextGrant(proposing ? 'read_all' : 'write_all'))) {
        return yield* new MerchandisePermissionDenied({
          code: 'merchandise_permission_denied',
          reason: proposing
            ? 'Návrhy AI vyžadují čtení objednávek'
            : 'Schvalovat a vracet změny AI může jen uživatel s právem zápisu do objednávek',
        });
      }
      if (!proposing && !staffCommandAllowed(legalEntityId, yield* administrator(), 'EditOrder')) {
        return yield* new MerchandisePermissionDenied({
          code: 'merchandise_permission_denied',
          reason: 'Schvalovat změny AI v objednávkách může jen správce',
        });
      }
      const head = yield* lockedHead(true);
      if (head.revision !== expectedRevision) {
        return yield* revisionConflict();
      }
      const working = yield* loadWorkingSet(
        transaction,
        store,
        head,
        aiWorkingSetRequest(command, head.aiChanges),
      ).pipe(Effect.mapError(unavailable));
      const now = yield* DateTime.now;
      const outcome = yield* applyMerchandiseAiCommand(
        working.state,
        command,
        {
          actor: { principalId: scope.principalId, tenantId: scope.tenantId },
          invocationId: resourceId,
          now,
        },
        {
          describeAddress,
          describeContact,
          describeLines,
          describeShipping,
          evolveMerchandiseState,
          orderStatusLabels,
        },
      ).pipe(
        Effect.mapError((failure) =>
          failure.kind === 'not_found' ? notFound(failure.message) : conflict(failure.message),
        ),
      );
      const revision = yield* persist(working, outcome.state, now);
      const entityIds = yield* Effect.forEach(outcome.entityIds, entityIdOf, { concurrency: 1 });
      return { entityIds, revision };
    });
    const apply = Effect.fn('Merchandise.apply')(function* apply(
      command: MerchandiseCommand,
      expectedRevision: number,
      resourceId: string,
    ) {
      if (isMerchandiseAiCommand(command)) {
        return yield* applyAi(command, expectedRevision, resourceId);
      }
      if (!(yield* contextGrant('write_all'))) {
        return yield* new MerchandisePermissionDenied({
          code: 'merchandise_permission_denied',
          reason: 'Merchandise changes require write permission',
        });
      }
      // People (also through an MCP connection, and agents acting through one) follow the AKROS staff split.
      if (
        (scope.authMethod === 'session' ||
          scope.authMethod === 'support_impersonation' ||
          scope.authMethod === 'oauth_connection') &&
        !staffCommandAllowed(legalEntityId, yield* administrator(), command._tag)
      ) {
        return yield* new MerchandisePermissionDenied({
          code: 'merchandise_permission_denied',
          reason: 'Tato změna vyžaduje oprávnění správce; expedice může zpracovávat objednávky a skladové pohyby',
        });
      }
      return yield* applyOnce(command, expectedRevision, resourceId);
    });
    const storefrontRecords = Effect.fn('Merchandise.storefrontRecords')(function* storefrontRecords(
      view: RecordsView,
    ) {
      const catalogQuery = view.storefrontCatalog;
      const page =
        catalogQuery === undefined || catalogQuery.mode === 'categories'
          ? undefined
          : yield* storefrontProducts(transaction, store, { query: catalogQuery });
      // Product pages carry their head in the same statement; category/order-only reads still need their revision.
      const head = page?.head ?? (yield* loadHead(transaction, store));
      if (head === undefined) {
        return yield* unavailable();
      }
      const { homepageFeaturedProductIds: featuredIds, revision } = head;
      const tree =
        catalogQuery === undefined ||
        (catalogQuery.includeCategories === false && catalogQuery.includeCategoryContent !== true)
          ? undefined
          : yield* categoryTree(transaction, store, {
              activeSlug: catalogQuery.categorySlug,
              contentOnly: catalogQuery.includeCategories === false,
              storefront: true,
            });
      const status =
        view.storefrontOrderStatus === undefined
          ? undefined
          : yield* storefrontOrderStatus(transaction, store, view.storefrontOrderStatus);
      const customerOrders =
        view.storefrontCustomerOrders === undefined
          ? undefined
          : yield* storefrontCustomerOrders(transaction, store, view.storefrontCustomerOrders);
      const pageProducts = page?.products ?? [];
      const response: Mutable<RecordsResponse> = {
        actorPrincipalRef: { principalId: scope.principalId, tenantId: scope.tenantId },
        canCleanupDemo: false,
        canEditOrders: false,
        canManageCatalog: false,
        canWrite: false,
        indicators: {
          lowStockCount: pageProducts.filter((record) => record.lowStock).length,
          openOrderValueMinor: 0,
          orderCount: 0,
          productCount: pageProducts.length,
          stockValueMinor: 0,
        },
        movements: [],
        orders: customerOrders?.orders ?? [],
        products: [...pageProducts],
        revision,
      };
      if (customerOrders !== undefined) {
        response.totalOrders = customerOrders.total;
      }
      if (view.storefrontCheckout === true) {
        response.checkout = {
          carrierTrackingAvailable: false,
          paymentAvailable: false,
          // No pickup-point registry exists. Do not offer a pickup method without real locations.
          shippingMethods: (['PPL', 'CESKA_POSTA'] as const).map((id) => ({
            id,
            priceMinor: shippingMethods[id].grossPriceMinor,
            title: shippingMethods[id].label,
          })),
        };
      }
      if (page !== undefined) {
        response.homepageFeaturedProductIds = featuredIds.map((id) => ProductIdReferenceSchema.make(id));
        response.page = page.page;
        response.pageSize = page.pageSize;
        response.total = page.total;
        response.totalProducts = page.total;
      }
      if (tree !== undefined) {
        response.categories = [...tree];
      }
      if (status !== undefined) {
        response.orderStatus = Option.fromNullishOr(status);
      }
      return response;
    });
    const readOrderPage = Effect.fn('Merchandise.readOrderPage')(function* readOrderPage(
      view: RecordsView,
      storefront: boolean,
    ): Effect.fn.Return<OrderReadPage, MerchandisePersistenceUnavailable> {
      if (!storefront) {
        return yield* orderPage(transaction, store, view).pipe(Effect.mapError(unavailable));
      }
      if (view.orderClientRequestId === undefined) {
        return { orders: [] };
      }
      return {
        orders: yield* ordersByClientRequest(transaction, store, view.orderClientRequestId).pipe(
          Effect.mapError(unavailable),
        ),
      };
    });
    const readCatalogMetadata = Effect.fn('Merchandise.readCatalogMetadata')(function* readCatalogMetadata(
      view: RecordsView,
      staff: boolean,
      pageProducts: RecordsResponse['products'],
    ) {
      const metadata: Mutable<CatalogReadMetadata> = {};
      let tree: RecordsResponse['categories'];
      if (staff && view.includeCategories === true) {
        tree = yield* categoryTree(transaction, store, { activeId: view.categoryId, storefront: false }).pipe(
          Effect.mapError(unavailable),
        );
        metadata.categories = [...tree];
      }
      let hasTree: boolean | undefined;
      if (staff && (view.includeProductCategories === true || view.categoryTrails === true)) {
        hasTree =
          tree === undefined
            ? yield* hasCategoryTree(transaction, store).pipe(Effect.mapError(unavailable))
            : tree.length > 0;
        metadata.hasCategoryTree = hasTree;
      }
      // Product category labels stand in for the storefront tree only when the company has no tree.
      if (staff && view.includeProductCategories === true && hasTree === false) {
        metadata.productCategories = [
          ...(yield* productCategoryCounts(transaction, store).pipe(Effect.mapError(unavailable))),
        ];
      }
      if (staff && view.categorySearch !== undefined) {
        const categorySearch = yield* searchCategoryTrails(transaction, store, view.categorySearch).pipe(
          Effect.mapError(unavailable),
        );
        metadata.categoryMatches = [...categorySearch.matches];
        metadata.categoryMatchTotal = categorySearch.total;
      }
      if (staff && view.categoryTrails === true) {
        const ids = pageProducts.flatMap((product) => (product.categoryId === undefined ? [] : [product.categoryId]));
        if (view.categoryId !== undefined) {
          ids.push(view.categoryId);
        }
        metadata.categoryTrails = [
          ...(yield* categoryTrailsOf(transaction, store, ids).pipe(Effect.mapError(unavailable))),
        ];
      }
      return metadata;
    });
    /** `detailLimit` lifts the 2-product cap of variant-carrying pages for in-process callers (agent review). */
    /** The records read's transaction step: database queries only; rights come from {@link merchandiseRecordsGrants}. */
    const records = Effect.fn('Merchandise.records')(function* records(
      request: RecordsRequest,
      grants: MerchandiseRecordsGrants,
      options: { readonly detailLimit?: number } = {},
    ) {
      const view = request.view ?? {};
      const storefront = view.storefront === true;
      const staff = !storefront;
      if (storefrontCatalogView(request)) {
        return yield* storefrontRecords(view).pipe(Effect.mapError(unavailable));
      }
      // A read-only or approval-only MCP connection cannot change the catalog directly.
      const canWrite = grants.writeAll && isConnectionWriteAllowed(scope, MERCHANDISE_MODULE_ID);
      const canRead = staff && (canWrite || grants.readAll);
      const headOptions: Mutable<HeadReadOptions> = { aiChanges: canRead };
      if (request.agentHistory !== undefined) {
        headOptions.history = request.agentHistory;
      }
      const head = yield* loadHead(transaction, store, headOptions).pipe(Effect.mapError(unavailable));
      if (head === undefined) {
        return yield* unavailable();
      }
      if (request.agentHistory !== undefined) {
        const response: Mutable<RecordsResponse> = {
          actorPrincipalRef: { principalId: scope.principalId, tenantId: scope.tenantId },
          canWrite,
          indicators: { lowStockCount: 0, openOrderValueMinor: 0, orderCount: 0, productCount: 0, stockValueMinor: 0 },
          movements: [],
          orders: [],
          products: [],
          revision: head.revision,
        };
        if (canRead && head.aiChanges !== undefined) {
          response.aiChanges = head.aiChanges;
        }
        return response;
      }
      const page = yield* staffProducts(transaction, store, view, storefront, options).pipe(
        Effect.mapError(unavailable),
      );
      const movements =
        staff && view.productId !== undefined
          ? yield* productMovements(transaction, store, view.productId).pipe(Effect.mapError(unavailable))
          : [];
      const [orderList, catalogMetadata] = yield* Effect.all(
        [readOrderPage(view, storefront), readCatalogMetadata(view, staff, page.products)],
        { concurrency: 1 },
      );
      // The storefront view never reveals staff totals: its indicators cover only what the view returns.
      const totals = staff
        ? yield* indicators(transaction, store).pipe(Effect.mapError(unavailable))
        : {
            lowStockCount: page.products.filter((record) => record.lowStock).length,
            openOrderValueMinor: 0,
            orderCount: orderList.orders.length,
            productCount: page.products.length,
            stockValueMinor: 0,
          };
      const storefrontOrigin = legalEntityId === AKROS_LEGAL_ENTITY_ID ? AKROS_STOREFRONT_ORIGIN : STOREFRONT_ORIGIN;
      const response: Mutable<RecordsResponse> = {
        ...catalogMetadata,
        actorPrincipalRef: { principalId: scope.principalId, tenantId: scope.tenantId },
        ...recordCapabilities(legalEntityId, storefront, grants, canWrite),
        canWrite,
        indicators: totals,
        movements: [...movements],
        orders: [...orderList.orders],
        products: [...page.products],
        revision: head.revision,
        totalProducts: page.total,
      };
      if (canRead && head.aiChanges !== undefined) {
        response.aiChanges = head.aiChanges;
      }
      if (orderList.total !== undefined) {
        response.totalOrders = orderList.total;
      }
      return storefrontOrigin === undefined ? response : { ...response, storefrontOrigin };
    });
    return { apply, records };
  },
  Effect.mapError((cause) =>
    Object.defineProperty(
      new OperationContextUnavailable({
        code: 'operation_context_unavailable',
        reason: 'Owner-scoped services are temporarily unavailable',
      }),
      'cause',
      { enumerable: false, value: cause },
    ),
  ),
);
